// BroadcastAddr returns the broadcast address of an IPNet.
// For IPv6 this returns the last address in the prefix range.
func BroadcastAddr(n *protoIp.IPNet) *protoIp.IPAddr {
	if n == nil {
		return nil
	}
	prefix := protoToPrefix(n)
	masked := prefix.Masked()
	addr := masked.Addr()

	if addr.Is4() {
		a := addr.As4()
		bits := masked.Bits()
		hostBits := 32 - bits
		if hostBits == 0 {
			return addrToProto(addr)
		}
		mask := uint32((1 << hostBits) - 1)
		v := uint32(a[0])<<24 | uint32(a[1])<<16 | uint32(a[2])<<8 | uint32(a[3])
		v |= mask
		bc := netip.AddrFrom4([4]byte{byte(v >> 24), byte(v >> 16), byte(v >> 8), byte(v)})
		return addrToProto(bc)
	}

	// IPv6
	b := addr.As16()
	bits := masked.Bits()
	hostBits := 128 - bits
	if hostBits == 0 {
		return addrToProto(addr)
	}
	// Set all host bits to 1
	for i := 15; i >= 0 && hostBits > 0; i-- {
		if hostBits >= 8 {
			b[i] = 0xff
			hostBits -= 8
		} else {
			b[i] |= byte((1 << hostBits) - 1)
			hostBits = 0
		}
	}
	bc := netip.AddrFrom16(b)
	return addrToProto(bc)
}

