// aggregatePrefixes sorts, deduplicates, and merges adjacent/overlapping prefixes.
func aggregatePrefixes(prefixes []netip.Prefix) []netip.Prefix {
	if len(prefixes) == 0 {
		return nil
	}

	// Sort by address then by prefix length
	sort.Slice(prefixes, func(i, j int) bool {
		ai, aj := prefixes[i].Addr(), prefixes[j].Addr()
		cmp := ai.Compare(aj)
		if cmp != 0 {
			return cmp < 0
		}
		return prefixes[i].Bits() < prefixes[j].Bits()
	})

	// Remove contained prefixes
	var stack []netip.Prefix
	for _, p := range prefixes {
		// If current prefix is contained in the last one on the stack, skip it
		if len(stack) > 0 && stack[len(stack)-1].Overlaps(p) && stack[len(stack)-1].Bits() <= p.Bits() {
			continue
		}
		stack = append(stack, p)
	}

	// Merge adjacent siblings (same prefix length, differ only in last bit of network)
	changed := true
	for changed {
		changed = false
		var merged []netip.Prefix
		i := 0
		for i < len(stack) {
			if i+1 < len(stack) && canMerge(stack[i], stack[i+1]) {
				// Merge into parent prefix (one bit shorter)
				parent := netip.PrefixFrom(stack[i].Addr(), stack[i].Bits()-1).Masked()
				merged = append(merged, parent)
				i += 2
				changed = true
			} else {
				merged = append(merged, stack[i])
				i++
			}
		}
		stack = merged
	}

	return stack
}

// canMerge returns true if two prefixes are adjacent siblings that can combine
// into a single prefix one bit shorter.
func canMerge(a, b netip.Prefix) bool {
	if a.Bits() != b.Bits() || a.Bits() == 0 {
		return false
	}
	// They must be the two halves of a parent prefix one bit shorter
	parent := netip.PrefixFrom(a.Addr(), a.Bits()-1).Masked()
	return parent == netip.PrefixFrom(b.Addr(), b.Bits()-1).Masked()
}

// ParseIPNets parses a comma-separated list of CIDR strings into an IPNets proto.
func ParseIPNets(s string) (*protoIp.IPNets, error) {
	if s == "" {
		return &protoIp.IPNets{}, nil
	}
	parts := strings.Split(s, ",")
	nets := &protoIp.IPNets{Nets: make([]*protoIp.IPNet, 0, len(parts))}
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		n, err := ParseIPNet(part)
		if err != nil {
			return nil, err
		}
		nets.Nets = append(nets.Nets, n)
	}
	return nets, nil
}

// FormatIPNets formats an IPNets proto to a comma-separated CIDR string.
func FormatIPNets(nets *protoIp.IPNets) string {
	if nets == nil || len(nets.Nets) == 0 {
		return ""
	}
	parts := make([]string, len(nets.Nets))
	for i, n := range nets.Nets {
		parts[i] = FormatIPNet(n)
	}
	return strings.Join(parts, ",")
}
